--
-- Table structure for table `wf_model`
--

DROP TABLE IF EXISTS `wf_model`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_model` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `model_key` varchar(64) NOT NULL COMMENT '模型标识(即流程定义key)',
  `model_name` varchar(200) NOT NULL COMMENT '模型名称',
  `category` varchar(50) DEFAULT NULL COMMENT '分类:EXPENSE费用/BUDGET预算/CONTRACT合同/PAYMENT付款',
  `bpmn_xml` longtext COMMENT 'BPMN2.0 XML',
  `form_json` longtext COMMENT '表单/节点配置JSON(设计器产物)',
  `version` int NOT NULL DEFAULT '1' COMMENT '模型版本',
  `deploy_id` varchar(64) DEFAULT NULL COMMENT '最近一次部署ID(Flowable)',
  `proc_def_id` varchar(64) DEFAULT NULL COMMENT '最近一次流程定义ID(Flowable)',
  `status` varchar(20) NOT NULL DEFAULT 'DRAFT' COMMENT '状态:DRAFT草稿/DEPLOYED已部署/DISABLED已停用',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  `biz_type` varchar(32) DEFAULT NULL COMMENT '业务单据类型(模板模型)',
  `source` varchar(16) DEFAULT 'USER' COMMENT 'TEMPLATE 需求模板 / USER 用户自定义',
  `org_scope` varchar(16) NOT NULL DEFAULT 'ALL' COMMENT '生效组织范围 ALL全集团 ORG指定公司',
  `org_ids` varchar(500) DEFAULT NULL COMMENT '适用公司ID列表(逗号分隔，org_scope=ORG时生效)',
  `allow_withdraw` tinyint NOT NULL DEFAULT '1' COMMENT '允许撤回 1是/0否',
  `reject_strategy` varchar(20) NOT NULL DEFAULT 'TO_INITIATOR' COMMENT '驳回策略 TO_INITIATOR驳回至发起人/TO_PREV驳回至上一节点',
  `enable_delegate` tinyint NOT NULL DEFAULT '1' COMMENT '开启代理审批 1是/0否',
  `exclude_org_ids` varchar(500) DEFAULT NULL COMMENT '排除组织公司ID列表(逗号分隔)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_model_key` (`tenant_id`,`model_key`),
  KEY `idx_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=229 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程模型';
/*!40101 SET character_set_client = @saved_cs_client */;

