INSERT INTO `wf_model` VALUES (101,1,'LOAN','借款与还款审批流程','EXPENSE','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<bpmn:definitions xmlns:bpmn=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:dc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:di=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:flowable=\"http://flowable.org/bpmn\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" id=\"Definitions_LOAN\" targetNamespace=\"http://fssc\">\n  <bpmn:process id=\"LOAN\" name=\"借款与还款审批流程（借款正向/还款反向档）\" isExecutable=\"true\">\n    <bpmn:startEvent id=\"StartEvent_1\" name=\"开始\" />\n    <bpmn:exclusiveGateway id=\"GW_LN\" name=\"借贷方向分档\" default=\"Flow_in_Task_1\" />\n    <bpmn:sequenceFlow id=\"Flow_start_gw\" sourceRef=\"StartEvent_1\" targetRef=\"GW_LN\" />\n    <bpmn:userTask id=\"Task_1\" name=\"借款申请【员工】\" flowable:candidateGroups=\"COMMON_EMP\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_1\" sourceRef=\"GW_LN\" targetRef=\"Task_1\" />\n    <bpmn:userTask id=\"Task_2\" name=\"直属上级审核【部门负责人】\" flowable:candidateGroups=\"DIRECT_SUPERVISOR\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_2\" sourceRef=\"Task_1\" targetRef=\"Task_2\" />\n    <bpmn:userTask id=\"Task_3\" name=\"部门经理审核【部门经理】\" flowable:candidateGroups=\"DEPT_MANAGER\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_3\" sourceRef=\"Task_2\" targetRef=\"Task_3\" />\n    <bpmn:userTask id=\"Task_4\" name=\"项目经理审核【项目经理】\" flowable:candidateGroups=\"PROJECT_MANAGER\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_4\" sourceRef=\"Task_3\" targetRef=\"Task_4\" />\n    <bpmn:userTask id=\"Task_5\" name=\"基地总经理审批【基地总经理】\" flowable:candidateGroups=\"BASE_GM\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_5\" sourceRef=\"Task_4\" targetRef=\"Task_5\" />\n    <bpmn:userTask id=\"Task_6\" name=\"财务总监审批【财务总监】\" flowable:candidateGroups=\"CFO\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_6\" sourceRef=\"Task_5\" targetRef=\"Task_6\" />\n    <bpmn:userTask id=\"Task